#!/usr/bin/env bash
set -euo pipefail
ROUND="${1:?r1 or r2}";[[ "$ROUND" == r1 || "$ROUND" == r2 ]]||exit 2
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")"&&pwd)";PROJECT="$(cd "$HERE/../../.."&&pwd)";REPO="$(cd "$PROJECT/.."&&pwd)";cd "$REPO"
if command -v module >/dev/null 2>&1;then module purge >/dev/null 2>&1||true;module load StdEnv/2023 python/3.11 rdkit/2025.09.4;module load cuda/12.6 2>/dev/null||true;fi
PY="${SUCC_PYTHON_BIN:-/home/bdong/.venvs/molscribe_overlay/bin/python}";SEED=7;P811="$PROJECT/outputs/p8_1_1_short_transaction_r1/seed_${SEED}";P6="$PROJECT/outputs/p6_unified_transition_policy_v1/seed_${SEED}";DIRECT="$PROJECT/outputs/direct_smiles_denovo_2p7p_v2_mixed_condition";SUITE="$PROJECT/outputs/unified_smiles_generator_suite_v1";JOINT="$PROJECT/outputs/unified_smiles_generator_joint_v2";LEGACY="$PROJECT/outputs/direct_smiles_denovo_2p7p_v2_group_rl_v1/direct_smiles_model_group_rl/direct_smiles_generator_rl.pt";BASE="$P811/policy/umtp_graph_action_policy.pt";OUT="$PROJECT/outputs/p8_2_state_adaptive_molprogram/transaction_group_rl/$ROUND/seed_${SEED}";mkdir -p "$OUT/policy" "$OUT/eval/denovo" "$OUT/eval/edit"
for x in "$LEGACY" "$BASE" "$P811/policy/training_summary.json" "$P811/data/edit_train.csv" "$P6/data/edit_table1_gate.csv" "$P6/data/denovo_hard_gate.csv";do [[ -s "$x" ]]||{ echo "missing $x" >&2;exit 2;};done
export PYTHONPATH="$PROJECT:$PROJECT/experiments/unified_smiles_generator:$PROJECT/experiments/p8_1_1_short_transaction:$PROJECT/experiments/p8_1_9_transaction_outcome_distill${PYTHONPATH:+:$PYTHONPATH}" OMP_NUM_THREADS="${SLURM_CPUS_PER_TASK:-8}" MKL_NUM_THREADS="${SLURM_CPUS_PER_TASK:-8}" TOKENIZERS_PARALLELISM=false
AGG=joint_bottleneck;[[ "$ROUND" == r2 ]]&&AGG=dense_softmin
"$PY" "$HERE/group_relative_transaction_rl.py" --base-checkpoint "$BASE" --base-training-summary "$P811/policy/training_summary.json" --train-csv "$P811/data/edit_train.csv" --features-dir "$SUITE/feature_variants/train_condition_features_hf_vlm" --edit-eval-csv "$P6/data/edit_table1_gate.csv" --denovo-eval-csv "$P6/data/denovo_hard_gate.csv" --output-dir "$OUT/policy" --audit-output "$OUT/training_audit.json" --reward-aggregation "$AGG" --rollouts 4 --max-prompts "${P82_MAX_PROMPTS:-128}" --lr 2e-6 --temperature .8 --reference-kl-weight .05 --sft-weight .10 --seed "$SEED" --device auto
CKPT="$OUT/policy/umtp_graph_action_policy.pt"
"$PY" "$HERE/audit_checkpoint.py" --legacy-base "$LEGACY" --rl-base "$BASE" --checkpoint "$CKPT" --training-audit "$OUT/training_audit.json" --output "$OUT/pre_eval_audit.json"
"$PY" "$PROJECT/experiments/p8_1_1_short_transaction/sample_raw_denovo.py" --checkpoint "$CKPT" --eval-csv "$P6/data/denovo_hard_gate.csv" --eval-features-dir "$DIRECT/eval_condition_features_hf_vlm" --output-csv "$OUT/eval/denovo/candidates.csv" --summary-json "$OUT/eval/denovo/sampling_summary.json" --num-samples 20 --seed 1982 --device auto
"$PY" "$PROJECT/experiments/p6_unified_molecular_transition_policy/evaluate_p6_denovo_gate.py" --eval-csv "$P6/data/denovo_hard_gate.csv" --candidates-csv "$OUT/eval/denovo/candidates.csv" --output-json "$OUT/eval/denovo/metrics.json" --output-md "$OUT/eval/denovo/report.md" --budgets 1,8,20
"$PY" "$PROJECT/experiments/p8_1_1_short_transaction/sample_raw_transactions.py" --checkpoint "$CKPT" --eval-csv "$P6/data/edit_table1_gate.csv" --eval-features-dir "$JOINT/feature_variants/validation_condition_features_hf_vlm" --output-csv "$OUT/eval/edit/candidates.csv" --summary-json "$OUT/eval/edit/sampling_summary.json" --num-samples 20 --temperature .8 --seed 2982 --device auto
for k in 1 8 20;do "$PY" "$PROJECT/scripts/evaluate_moledit_table1_anyk.py" --reference "$P6/data/edit_table1_gate.csv" --candidates "$OUT/eval/edit/candidates.csv" --output-dir "$OUT/eval/edit/any${k}" --candidate-limit "$k" --model-name "p8_2_transaction_${ROUND}_any${k}" --task-filter table1 --missing-oracle-policy fail;done
"$PY" "$PROJECT/scripts/evaluate_moledit_table1_anyk.py" --reference "$P6/data/edit_table1_gate.csv" --candidates "$OUT/eval/edit/candidates.csv" --output-dir "$OUT/eval/edit/candidate20" --candidate-limit 20 --aggregation candidate --model-name "p8_2_transaction_${ROUND}_candidate20" --task-filter table1 --missing-oracle-policy fail
"$PY" "$HERE/audit_checkpoint.py" --legacy-base "$LEGACY" --rl-base "$BASE" --checkpoint "$CKPT" --training-audit "$OUT/training_audit.json" --denovo-summary "$OUT/eval/denovo/sampling_summary.json" --edit-summary "$OUT/eval/edit/sampling_summary.json" --output "$OUT/final_audit.json";touch "$OUT/COMPLETE"
